<?php

declare(strict_types=1);

namespace App\Tests\E2E;

use App\Platform\Settings\ConfigRevision;
use App\Tests\Support\AdminSession;
use App\Tests\Support\Fixtures;
use App\Tests\Support\TestContainer;
use PHPUnit\Framework\TestCase;

/**
 * Proof that the module generated by Enterprise Gii (`./yii gii:module Contracts … --apply`, then
 * migrate:up + rbac:sync) is integrated in the running stack, and that the Enterprise Gii admin page works:
 * preview of the same spec reports every file as "unchanged" (the committed sample equals the generator output).
 */
final class GiiGeneratedModuleTest extends TestCase
{
    private const FIELDS = 'title:string:required:max=255,amount:decimal:min=0,status:enum(draft|active|closed),due_on:date,owner_id:user';

    protected function setUp(): void
    {
        Fixtures::resetLoginThrottle();
        TestContainer::service(ConfigRevision::class)->bump();
    }

    protected function tearDown(): void
    {
        Fixtures::cleanup();
    }

    public function testGeneratedModuleIsServedInAdminWebAndApi(): void
    {
        [$web] = AdminSession::login(['superadmin']);
        $r = $web->get('/admin/contracts');
        self::assertSame(200, $r->getStatusCode(), substr($web->body(), 0, 500));
        self::assertStringContainsString('<h1>Contracts</h1>', $web->body());
        self::assertStringContainsString('New contract', $web->body());
        self::assertStringContainsString('hx-get="/admin/contracts"', $web->body());

        $title = 'Gii proof ' . bin2hex(random_bytes(3));
        $web->get('/admin/contracts/create');
        $web->post('/admin/contracts/create', ['title' => $title, 'amount' => '1500.00', 'due_on' => '2026-12-31']);
        self::assertMatchesRegularExpression('#^/admin/contracts/[0-9a-f-]{36}$#', $web->url());
        self::assertStringContainsString($title, $web->body());
        self::assertStringContainsString('1 500.00', $web->body());

        self::assertSame(200, $web->get('/contracts')->getStatusCode(), 'web UI');
        self::assertStringContainsString($title, $web->body());

        $web->get('/admin/modules');
        self::assertStringContainsString('contracts', $web->body(), 'listed in Business modules');

        $doc = json_decode((string) $web->get('/api/v1/openapi.json')->getBody(), true);
        self::assertArrayHasKey('/api/v1/contracts', $doc['paths'] ?? []);
        self::assertArrayHasKey('Contract', $doc['components']['schemas'] ?? []);
    }

    public function testEnterpriseGiiPagePreviewsWithoutWriting(): void
    {
        [$web] = AdminSession::login(['superadmin']);
        $r = $web->get('/admin/devtools/gii');
        if ($r->getStatusCode() === 404) {
            self::markTestSkipped('Enterprise Gii is unavailable here (prod, flag devtools.gii off or yii-gii not installed).');
        }
        self::assertSame(200, $r->getStatusCode());
        self::assertStringContainsString('Enterprise Gii', $web->body());
        self::assertStringContainsString('name="generators[]" value="workflow"', $web->body());

        // the committed Contracts module equals the generator output → everything "unchanged"
        $r = $web->post('/admin/devtools/gii/preview', ['module' => 'Contracts', 'fields' => self::FIELDS, 'generators' => ['entity', 'crud', 'rbac', 'event', 'workflow', 'notification', 'job', 'report', 'scheduler', 'connector', 'admin', 'web', 'api', 'tests']]);
        self::assertSame(200, $r->getStatusCode(), substr($web->body(), 0, 800));
        self::assertStringContainsString('src/Modules/Contracts/Domain/Contract.php', $web->body());
        self::assertStringContainsString('unchanged 43', $web->body());
        self::assertStringNotContainsString('gii-file--new', $web->body());

        // validation: invalid module name / field spec → 422 with messages, nothing generated
        $r = $web->post('/admin/devtools/gii/preview', ['module' => '../evil', 'fields' => 'id:string']);
        self::assertSame(422, $r->getStatusCode());
        self::assertStringContainsString('^[A-Z][A-Za-z0-9]{2,40}$', html_entity_decode($web->body()));

        // a module that does not exist yet: preview lists new files, but nothing is written
        $r = $web->post('/admin/devtools/gii/preview', ['module' => 'GiiProbes', 'fields' => 'name:string:required', 'generators' => ['crud']]);
        self::assertSame(200, $r->getStatusCode());
        self::assertStringContainsString('src/Modules/GiiProbes/Application/GiiProbeService.php', $web->body());
        self::assertFileDoesNotExist(dirname(__DIR__, 2) . '/src/Modules/GiiProbes/module.php', 'preview is a dry run');

        // apply without the explicit confirmation (and behind RequireRecentAuth) writes nothing
        $web->post('/admin/devtools/gii/apply', ['module' => 'GiiProbes', 'fields' => 'name:string:required', 'generators' => ['crud']]);
        self::assertFileDoesNotExist(dirname(__DIR__, 2) . '/src/Modules/GiiProbes/module.php', 'apply without confirmation must not write');
    }

    public function testGiiPageRequiresDevtoolsPermission(): void
    {
        [$web] = AdminSession::login(['auditor']);
        self::assertContains($web->get('/admin/devtools/gii')->getStatusCode(), [403, 404]);
    }
}
